    {
      "symbol": "💸",
      "tooltip": "verification tax is like a money with wings, it represents the drain of capital away from R&D and into the coffers of private audit firms"
    }
  ],
  "claim_sketches": [
    {
      "claim": "The 'Performance-Based Escape Hatch' is a distinction without a difference because the cost of independent, third-party empirical verification creates a 'verification tax' that is functionally identical to the 'compliance ceiling'.",
      "targets": [
        "AN-28"
      ]
    },
    {
      "claim": "By mandating external validation, we simply shift the barrier from administrative paperwork to expensive, specialized audit services that only established firms can afford.",
      "targets": [
        "AN-28"
      ]
    },
    {
      "claim": "Safetyist argues that this verification serves as 'skin-in-the-game,' but in practice, it functions as 'capital-in-the-game.'",
      "targets": [
        "AN-29"
      ]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "The cost of third-party verification is high enough to act as a prohibitive barrier for startups.",
      "if_wrong": "If verification services become cheap and automated, the 'verification tax' would be negligible, potentially validating the escape hatch as a viable path for innovators."
    },
    {
      "assumption": "The market for high-capability safety auditors is not sufficiently competitive to prevent price gouging.",
